from abc import ABCMeta, abstractmethod
import logging
import six

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@six.add_metaclass(ABCMeta)
class Process(object):
    """
    Running process with input and output streams.
    """

    def __init__(self, command, stdin, stdout, stderr, **kwargs):
        self._command = command
        self._stdin = stdin
        self._stdout = stdout
        self._stderr = stderr

    @property
    def stdin(self):
        return self._stdin

    @property
    def stdout(self):
        return self._stdout

    @property
    def stderr(self):
        return self._stderr

    @property
    def command(self):
        return self._command

    @abstractmethod
    def wait(self, timeout=None):
        """
        Wait until the process finishes execution.

        :param float timeout:
            wait timeout seconds for the process to finish
            (forever, if timeout is None)
        :raises: TimeoutError, if process did not finish after timeout seconds
        """

    @abstractmethod
    def _get_is_running(self):
        """
        Return True, if the process is still running.

        :return:
        """

    is_running = property(lambda self: self._get_is_running())

    @abstractmethod
    def _get_exit_status(self):
        """
        Return the exit status of a terminated process.

        :return: exit status
        :rtpye: int
        """

    exit_status = property(lambda self: self._get_exit_status())

    @abstractmethod
    def _read_output(self):
        """
        Read stdout and stderr from the process.

        Uses select() or similar techniques to avoid blocking when reading from streams.
        This method handles the problem of blocking due to > 64 kB data on either stdout
        or stderr by multiplexing between the two streams.

        This is an internal method without logging. Use read_output() for public API.

        :return: stdout data, stderr data
        :rtype: bytes, bytes
        """

    def read_output(self):
        """
        Read stdout and stderr from the process.

        Uses select() or similar techniques to avoid blocking when reading from streams.
        This method handles the problem of blocking due to > 64 kB data on either stdout
        or stderr by multiplexing between the two streams.

        This is a wrapper that logs the read operation and calls _read_output().

        :return: stdout data, stderr data
        :rtype: bytes, bytes
        """
        logger.debug("reading output from process")
        stdout, stderr = self._read_output()
        logger.debug(f"stdout={stdout!r}, stderr={stderr!r}")
        return stdout, stderr
